questionvariables.text:
cardn(S) := length(listify(S));
dset(S) := if emptyp(S) then "\\{\\,\\}" else sconcat("\\{", simplode(map(string, listify(S)), ", "), "\\}");
ix: 1+rand(10);
/* Design: give the region numbers for a set expression. Source: adapted from SMP Book 4, revision exercise, page 83, question 7. Curated list, one seed per entry.
   Regions: 1 first set only, 2 both, 3 second set only, 4 outside both. ta: answer, cp: its complement,
   sw: the answer with the operation swapped, sm: swap message; mi, ex, g: test sets; st: worked steps; sh: shading list. */
L: [["A","B",["A","B"],"A \\cup B",{1,2,3},{4},{2},"<p>You used \\(\\cap\\) where the expression has \\(\\cup\\), or the other way round.</p>",{1,2},{1,2,3,4},{1,2,4},"In region numbers, \\(A = \\{1, 2\\}\\) and \\(B = \\{2, 3\\}\\), so \\(A \\cup B = \\{1, 2, 3\\}\\).",[1,2,3],"(A \\cap B)'",{1,3,4},{2},{4},"<p>You used \\(\\cap\\) where the expression has \\(\\cup\\), or the other way round.</p>",{1,3},{1,2,3,4},{1,2,3},"In region numbers, \\(A \\cap B = \\{2\\}\\), so \\((A \\cap B)' = \\{1, 3, 4\\}\\).",[1,3,4],"A \\cup (A \\cup B)'",{1,2,4},{3},{1},"<p>You used \\(\\cap\\) where the expression has \\(\\cup\\), or the other way round.</p>",{1,2},{1,2,3,4},{1,2,3},"In region numbers, \\(A = \\{1, 2\\}\\) and \\((A \\cup B)' = \\{4\\}\\), so \\(A \\cup (A \\cup B)' = \\{1, 2, 4\\}\\).",[1,2,4]],
  ["F","N",["F","N"],"F \\cap N",{2},{1,3,4},{1,2,3},"<p>You used \\(\\cap\\) where the expression has \\(\\cup\\), or the other way round.</p>",{},{1,2},{1},"In region numbers, \\(F = \\{1, 2\\}\\) and \\(N = \\{2, 3\\}\\), so \\(F \\cap N = \\{2\\}\\).",[2],"(F - N)'",{2,3,4},{1},{1,2,4},"<p>You took the difference the wrong way round.</p>",{2,3},{1,2,3,4},{1,2,3},"In region numbers, \\(F - N = \\{1\\}\\), so \\((F - N)' = \\{2, 3, 4\\}\\).",[2,3,4],"(F \\cup N) \\cap F'",{3},{1,2,4},{2,3,4},"<p>You used \\(\\cap\\) where the expression has \\(\\cup\\), or the other way round.</p>",{},{1,3},{1},"In region numbers, \\(F \\cup N = \\{1, 2, 3\\}\\) and \\(F' = \\{3, 4\\}\\), so \\((F \\cup N) \\cap F' = \\{3\\}\\).",[3]],
  ["M","K",["M","K"],"M - K",{1},{2,3,4},{3},"<p>You took the difference the wrong way round.</p>",{},{1,2},{2},"In region numbers, \\(M = \\{1, 2\\}\\) and \\(K = \\{2, 3\\}\\), so \\(M - K = \\{1\\}\\).",[1],"M' \\cup K'",{1,3,4},{2},{4},"<p>You used \\(\\cap\\) where the expression has \\(\\cup\\), or the other way round.</p>",{1,3},{1,2,3,4},{1,2,3},"In region numbers, \\(M' = \\{3, 4\\}\\) and \\(K' = \\{1, 4\\}\\), so \\(M' \\cup K' = \\{1, 3, 4\\}\\).",[1,3,4],"(M \\cup K)' \\cup K",{2,3,4},{1},{3},"<p>You used \\(\\cap\\) where the expression has \\(\\cup\\), or the other way round.</p>",{2,3},{1,2,3,4},{1,2,3},"In region numbers, \\((M \\cup K)' = \\{4\\}\\) and \\(K = \\{2, 3\\}\\), so \\((M \\cup K)' \\cup K = \\{2, 3, 4\\}\\).",[2,3,4]],
  ["P","Q",["P","Q"],"Q - P",{3},{1,2,4},{1},"<p>You took the difference the wrong way round.</p>",{},{1,3},{2},"In region numbers, \\(Q = \\{2, 3\\}\\) and \\(P = \\{1, 2\\}\\), so \\(Q - P = \\{3\\}\\).",[3],"(Q - P)'",{1,2,4},{3},{2,3,4},"<p>You took the difference the wrong way round.</p>",{1,2},{1,2,3,4},{1,2,3},"In region numbers, \\(Q - P = \\{3\\}\\), so \\((Q - P)' = \\{1, 2, 4\\}\\).",[1,2,4],"P' - Q",{4},{1,2,3},{2},"<p>You took the difference the wrong way round.</p>",{},{1,4},{1},"In region numbers, \\(P' = \\{3, 4\\}\\) and \\(Q = \\{2, 3\\}\\), so \\(P' - Q = \\{4\\}\\).",[4]],
  ["S","T",["S","T"],"S \\cup T",{1,2,3},{4},{2},"<p>You used \\(\\cap\\) where the expression has \\(\\cup\\), or the other way round.</p>",{1,2},{1,2,3,4},{1,2,4},"In region numbers, \\(S = \\{1, 2\\}\\) and \\(T = \\{2, 3\\}\\), so \\(S \\cup T = \\{1, 2, 3\\}\\).",[1,2,3],"(S - T)'",{2,3,4},{1},{1,2,4},"<p>You took the difference the wrong way round.</p>",{2,3},{1,2,3,4},{1,2,3},"In region numbers, \\(S - T = \\{1\\}\\), so \\((S - T)' = \\{2, 3, 4\\}\\).",[2,3,4],"T' \\cup (S \\cap T)",{1,2,4},{3},{1},"<p>You used \\(\\cap\\) where the expression has \\(\\cup\\), or the other way round.</p>",{1,2},{1,2,3,4},{1,2,3},"In region numbers, \\(T' = \\{1, 4\\}\\) and \\(S \\cap T = \\{2\\}\\), so \\(T' \\cup (S \\cap T) = \\{1, 2, 4\\}\\).",[1,2,4]],
  ["C","D",["C","D"],"C \\cap D",{2},{1,3,4},{1,2,3},"<p>You used \\(\\cap\\) where the expression has \\(\\cup\\), or the other way round.</p>",{},{1,2},{1},"In region numbers, \\(C = \\{1, 2\\}\\) and \\(D = \\{2, 3\\}\\), so \\(C \\cap D = \\{2\\}\\).",[2],"(C \\cap D)'",{1,3,4},{2},{4},"<p>You used \\(\\cap\\) where the expression has \\(\\cup\\), or the other way round.</p>",{1,3},{1,2,3,4},{1,2,3},"In region numbers, \\(C \\cap D = \\{2\\}\\), so \\((C \\cap D)' = \\{1, 3, 4\\}\\).",[1,3,4],"(C \\cup D)' \\cup D",{2,3,4},{1},{3},"<p>You used \\(\\cap\\) where the expression has \\(\\cup\\), or the other way round.</p>",{2,3},{1,2,3,4},{1,2,3},"In region numbers, \\((C \\cup D)' = \\{4\\}\\) and \\(D = \\{2, 3\\}\\), so \\((C \\cup D)' \\cup D = \\{2, 3, 4\\}\\).",[2,3,4]],
  ["G","H",["G","H"],"G - H",{1},{2,3,4},{3},"<p>You took the difference the wrong way round.</p>",{},{1,2},{2},"In region numbers, \\(G = \\{1, 2\\}\\) and \\(H = \\{2, 3\\}\\), so \\(G - H = \\{1\\}\\).",[1],"(H - G)'",{1,2,4},{3},{2,3,4},"<p>You took the difference the wrong way round.</p>",{1,2},{1,2,3,4},{1,2,3},"In region numbers, \\(H - G = \\{3\\}\\), so \\((H - G)' = \\{1, 2, 4\\}\\).",[1,2,4],"(G \\cup H) \\cap G'",{3},{1,2,4},{2,3,4},"<p>You used \\(\\cap\\) where the expression has \\(\\cup\\), or the other way round.</p>",{},{1,3},{1},"In region numbers, \\(G \\cup H = \\{1, 2, 3\\}\\) and \\(G' = \\{3, 4\\}\\), so \\((G \\cup H) \\cap G' = \\{3\\}\\).",[3]],
  ["X","Y",["X","Y"],"Y - X",{3},{1,2,4},{1},"<p>You took the difference the wrong way round.</p>",{},{1,3},{2},"In region numbers, \\(Y = \\{2, 3\\}\\) and \\(X = \\{1, 2\\}\\), so \\(Y - X = \\{3\\}\\).",[3],"X' \\cup Y'",{1,3,4},{2},{4},"<p>You used \\(\\cap\\) where the expression has \\(\\cup\\), or the other way round.</p>",{1,3},{1,2,3,4},{1,2,3},"In region numbers, \\(X' = \\{3, 4\\}\\) and \\(Y' = \\{1, 4\\}\\), so \\(X' \\cup Y' = \\{1, 3, 4\\}\\).",[1,3,4],"X \\cup (X \\cup Y)'",{1,2,4},{3},{1},"<p>You used \\(\\cap\\) where the expression has \\(\\cup\\), or the other way round.</p>",{1,2},{1,2,3,4},{1,2,3},"In region numbers, \\(X = \\{1, 2\\}\\) and \\((X \\cup Y)' = \\{4\\}\\), so \\(X \\cup (X \\cup Y)' = \\{1, 2, 4\\}\\).",[1,2,4]],
  ["R","W",["R","W"],"R \\cup W",{1,2,3},{4},{2},"<p>You used \\(\\cap\\) where the expression has \\(\\cup\\), or the other way round.</p>",{1,2},{1,2,3,4},{1,2,4},"In region numbers, \\(R = \\{1, 2\\}\\) and \\(W = \\{2, 3\\}\\), so \\(R \\cup W = \\{1, 2, 3\\}\\).",[1,2,3],"(W - R)'",{1,2,4},{3},{2,3,4},"<p>You took the difference the wrong way round.</p>",{1,2},{1,2,3,4},{1,2,3},"In region numbers, \\(W - R = \\{3\\}\\), so \\((W - R)' = \\{1, 2, 4\\}\\).",[1,2,4],"R' - W",{4},{1,2,3},{2},"<p>You took the difference the wrong way round.</p>",{},{1,4},{1},"In region numbers, \\(R' = \\{3, 4\\}\\) and \\(W = \\{2, 3\\}\\), so \\(R' - W = \\{4\\}\\).",[4]],
  ["J","L",["J","L"],"J \\cap L",{2},{1,3,4},{1,2,3},"<p>You used \\(\\cap\\) where the expression has \\(\\cup\\), or the other way round.</p>",{},{1,2},{1},"In region numbers, \\(J = \\{1, 2\\}\\) and \\(L = \\{2, 3\\}\\), so \\(J \\cap L = \\{2\\}\\).",[2],"J' \\cup L'",{1,3,4},{2},{4},"<p>You used \\(\\cap\\) where the expression has \\(\\cup\\), or the other way round.</p>",{1,3},{1,2,3,4},{1,2,3},"In region numbers, \\(J' = \\{3, 4\\}\\) and \\(L' = \\{1, 4\\}\\), so \\(J' \\cup L' = \\{1, 3, 4\\}\\).",[1,3,4],"L' \\cup (J \\cap L)",{1,2,4},{3},{1},"<p>You used \\(\\cap\\) where the expression has \\(\\cup\\), or the other way round.</p>",{1,2},{1,2,3,4},{1,2,3},"In region numbers, \\(L' = \\{1, 4\\}\\) and \\(J \\cap L = \\{2\\}\\), so \\(L' \\cup (J \\cap L) = \\{1, 2, 4\\}\\).",[1,2,4]]];
la: L[ix][1]; lb: L[ix][2]; labs: L[ix][3]; e1: L[ix][4]; ta1: L[ix][5]; cp1: L[ix][6]; sw1: L[ix][7]; sm1: L[ix][8]; mi1: L[ix][9]; ex1: L[ix][10]; g1: L[ix][11]; st1: L[ix][12]; sh1: L[ix][13]; e2: L[ix][14]; ta2: L[ix][15]; cp2: L[ix][16]; sw2: L[ix][17]; sm2: L[ix][18]; mi2: L[ix][19]; ex2: L[ix][20]; g2: L[ix][21]; st2: L[ix][22]; sh2: L[ix][23]; e3: L[ix][24]; ta3: L[ix][25]; cp3: L[ix][26]; sw3: L[ix][27]; sm3: L[ix][28]; mi3: L[ix][29]; ex3: L[ix][30]; g3: L[ix][31]; st3: L[ix][32]; sh3: L[ix][33];
